:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #263b35;
  background: #f6efe2;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f6efe2;
  background-image: radial-gradient(#dfd2b9 1.5px, transparent 1.5px);
  background-size: 20px 20px;
}

.card {
  width: min(100%, 500px);
  padding: clamp(24px, 7vw, 44px);
  border: 3px solid #263b35;
  border-radius: 12px;
  background: #fffdf7;
  box-shadow: 8px 8px 0 #263b35;
}

.pixel-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin-bottom: 20px;
  border: 2px solid #263b35;
  border-radius: 8px;
  color: #fffdf7;
  background: #d96c4b;
  font-size: 27px;
}

.eyebrow {
  margin: 0 0 8px;
  color: #a84b32;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .12em;
}

h1 {
  margin: 0;
  font-size: clamp(2rem, 8vw, 2.8rem);
  line-height: 1.08;
  letter-spacing: -.04em;
}

.intro { margin: 16px 0 28px; color: #52645d; line-height: 1.55; }
.converter label { display: block; margin-bottom: 9px; font-weight: 750; }
.input-row { display: flex; gap: 10px; }

input, select {
  min-width: 0;
  min-height: 52px;
  padding: 10px 14px;
  border: 2px solid #9aa89e;
  border-radius: 7px;
  color: #263b35;
  background: #fffdf7;
  font: inherit;
  font-size: 1.05rem;
}

input { flex: 1; }
select { width: 48%; cursor: pointer; }
input:hover, select:hover { border-color: #d96c4b; }
input:focus-visible, select:focus-visible { outline: 3px solid #d96c4b; outline-offset: 3px; }

.results {
  margin-top: 30px;
  padding: 20px;
  border: 2px solid #d7e1d8;
  border-radius: 9px;
  background: #edf3eb;
}

h2 { margin: 0 0 14px; font-size: 1rem; }
.result-list { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.result-list li { display: flex; justify-content: space-between; gap: 12px; padding-bottom: 9px; border-bottom: 1px dashed #b8c8ba; }
.result-list li:last-child { padding-bottom: 0; border: 0; }
.result-value { font-weight: 800; font-variant-numeric: tabular-nums; }
.note { margin: 18px 0 0; color: #52645d; font-size: .9rem; text-align: center; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (max-width: 380px) {
  .card { padding: 22px 18px; }
  .results { padding: 16px; }
  select { width: 52%; }
}

const amountInput = document.getElementById('amount');
const unitSelect = document.getElementById('unit');
const resultList = document.getElementById('result-list');

const units = [
  { id: 'cups', label: 'Cups', cups: 1 },
  { id: 'tbsp', label: 'Tablespoons', cups: 1 / 16 },
  { id: 'tsp', label: 'Teaspoons', cups: 1 / 48 },
  { id: 'ml', label: 'Millilitres', cups: 1 / 240 }
];

function updateResults() {
  const amount = Number(amountInput.value);
  const selected = units.find(unit => unit.id === unitSelect.value);
  const totalCups = amount * selected.cups;
  resultList.replaceChildren();

  for (const unit of units) {
    if (unit.id === selected.id) continue;
    const value = (totalCups / unit.cups).toFixed(1);
    const item = document.createElement('li');
    const label = document.createElement('span');
    const result = document.createElement('span');
    label.textContent = unit.label;
    result.className = 'result-value';
    result.textContent = `${value} ${unit.id}`;
    item.append(label, result);
    resultList.append(item);
  }
}

amountInput.addEventListener('input', updateResults);
unitSelect.addEventListener('change', updateResults);
updateResults();
